    /// <summary>
    /// Finds the specified record in the <c>METSalesLineStatus</c> table.
    /// </summary>
    /// <param name="_reasonCode">
    /// The ReasonCode of the <c>METSalesLineStatus</c> record to find.
    /// </param>
    /// <param name="_forupdate">
    /// A Boolean value that indicates whether to read the record for update; optional.
    /// </param>
    /// <param name="_concurrencyModel">
    /// The ConcurrencyModel value set to; Auto.
    /// </param>
    /// <returns>
    /// A record in the <c>METSalesLineStatus</c> table; otherwise, an empty record.
    /// </returns>
    public static METSalesLineStatus find(
        ReasonCode _reasonCode ,
        boolean _forupdate = false,
        ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
    {
        METSalesLineStatus salesLineStatus;
        if(_reasonCode)
        {
            salesLineStatus.selectForUpdate(_forupdate);
            if (_forupdate && _concurrencyModel != ConcurrencyModel::Auto)
            {
                salesLineStatus.concurrencyModel(_concurrencyModel);
            }

            select firstonly salesLineStatus where salesLineStatus.ReasonCode == _reasonCode;
        }

        return salesLineStatus;
    }

    /// <summary>
    /// Exists the specified record in the <c>METSalesLineStatus</c> table.
    /// </summary>
    /// <param name = "_reasonCode">
    /// The ReasonCode of the <c>METSalesLineStatus</c> record to exists.
    /// </param>
    /// <returns>A Boolean value that indicates whether the record exists or not</returns>
    public static boolean exist(ReasonCode _reasonCode)
    {
        boolean found;

        found = (select firstonly
                     RecId
                from
                     METSalesLineStatus
                 where
                     METSalesLineStatus.ReasonCode == _reasonCode).RecId != 0;

        return found;
    }
